package com.jdvsn.mousedrop;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.input.MouseAdapter;

import javax.inject.Inject;
import java.awt.event.MouseEvent;

@Slf4j
public class MouseButtonDropMouseListener extends MouseAdapter
{

	@Inject
	private MouseButtonDropPlugin plugin;

	@Inject
	private MouseButtonDropConfig config;

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (e.getButton() == config.mouseButtonNumber())
		{
			plugin.setMouseButtonHeld(true);
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (e.getButton() == config.mouseButtonNumber())
		{
			plugin.setMouseButtonHeld(false);
			e.consume();
		}
		return e;
	}

}

package com.jdvsn.mousedrop;

import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class MouseDropMenuOverride
{
    @Inject
    private Client client;

    private final DropIndexCache dropIndexCache = new DropIndexCache();

    public void invoke(boolean mouseButtonHeld)
    {
        if (!mouseButtonHeld || client.isMenuOpen()) return;

        MenuEntry[] entries = client.getMenu().getMenuEntries();
        if (entries.length < 2) return;

        int topIdx = entries.length - 1;
        int itemId = entries[topIdx].getItemId();
        if (itemId < 1) return;

        if (itemId != dropIndexCache.itemId)
        {
            int dropIdx = findDropIdx(entries);
            if (dropIdx < 0 || dropIdx == topIdx)
            {
                return;
            }
            dropIndexCache.itemId = itemId;
            dropIndexCache.dropIdx = dropIdx;
            log.debug("Will swap dropIdx: {} with topIdx: {}", dropIdx, topIdx);
        }

        setLeftClickable(entries[dropIndexCache.dropIdx]);
        swapMenuEntries(entries, topIdx, dropIndexCache.dropIdx);
        client.getMenu().setMenuEntries(entries);
    }

    private void setLeftClickable(MenuEntry entry)
    {
        entry.setType(MenuAction.CC_OP);
    }

    private int findDropIdx(MenuEntry[] entries)
    {
        int dropIdx = -1;
        for (int i = 0; i < entries.length; i++)
        {
            log.debug("[{}] {}", i, entries[i].getOption());
            MenuEntry en = entries[i];
            if ("Drop".equals(en.getOption()))
            {
                return i;
            }
        }
        log.debug("Drop not found");
        return dropIdx;
    }

    private void swapMenuEntries(MenuEntry[] entries, int topIdx, int dropIdx)
    {
        MenuEntry tmp = entries[topIdx];
        entries[topIdx] = entries[dropIdx];
        entries[dropIdx] = tmp;
    }

    @Data
    private static class DropIndexCache
    {
        private int itemId = -1;
        private int dropIdx = -1;
    }
}

package com.jdvsn.mousedrop;

import net.runelite.client.config.*;

@ConfigGroup("mousebuttondrop")
public interface MouseButtonDropConfig extends Config
{

	@ConfigSection(
			name = "Mouse Button Drop",
			description = "Settings for mouse button dropping",
			position = 1
	)
	String mouseButtonSubject = "mousebuttondrop";

	@Range(
			min = 4,
			max = 9
	)
	@ConfigItem(
			position = 1,
			keyName = "mouseButtonNumber",
			name = "Mouse button number",
			description = "The mouse button number to hold for left-click dropping (between 4 and 9)",
			section = mouseButtonSubject
	)
	default int mouseButtonNumber()
	{
		return 4;
	}
}

package com.jdvsn.mousedrop;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;

@PluginDescriptor(
        name = "Mouse Button Drop",
        description = "Hold a mouse button (eg. MB4) to left-click drop items as if you were holding shift",
        tags = {"mouse", "button", "drop"},
        enabledByDefault = true
)
@Slf4j
public class MouseButtonDropPlugin extends Plugin {
    @Inject
    private MouseManager mouseManager;

    @Inject
    private MouseButtonDropMouseListener mouseListener;

    @Inject
    private ConfigManager configManager;

    @Inject
    private MouseDropMenuOverride mouseDropMenuOverride;

    @Getter
    @Setter
    private boolean mouseButtonHeld = false;

    @Override
    protected void startUp() throws Exception {
        mouseManager.registerMouseListener(mouseListener);
        configManager.setConfiguration("runelite", "blockExtraMouseButtons", false);
    }

    @Override
    protected void shutDown() throws Exception {
        mouseManager.unregisterMouseListener(mouseListener);
    }

    @Subscribe
    public void onPostMenuSort(PostMenuSort postMenuSort) {
        mouseDropMenuOverride.invoke(mouseButtonHeld);
    }

    @Provides
    MouseButtonDropConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(MouseButtonDropConfig.class);
    }
}
